CREATE TYPE "OrgRole" AS ENUM ('ORG_ADMIN','MEMBER');
CREATE TYPE "TaskStatus" AS ENUM ('TODO','IN_PROGRESS','REVIEW','DONE');
CREATE TYPE "TaskPriority" AS ENUM ('LOW','MEDIUM','HIGH','URGENT');
CREATE TYPE "OutboxStatus" AS ENUM ('PENDING','PUBLISHED','FAILED');
CREATE TABLE "users" ("id" TEXT PRIMARY KEY,"email" TEXT NOT NULL UNIQUE,"password_hash" TEXT NOT NULL,"name" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "organizations" ("id" TEXT PRIMARY KEY,"name" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "org_members" ("id" TEXT PRIMARY KEY,"org_id" TEXT NOT NULL REFERENCES "organizations"("id") ON DELETE CASCADE,"user_id" TEXT NOT NULL REFERENCES "users"("id") ON DELETE CASCADE,"role" "OrgRole" NOT NULL DEFAULT 'MEMBER',"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("org_id","user_id"));
CREATE TABLE "projects" ("id" TEXT PRIMARY KEY,"org_id" TEXT NOT NULL REFERENCES "organizations"("id") ON DELETE CASCADE,"name" TEXT NOT NULL,"description" TEXT,"deleted_at" TIMESTAMP(3),"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "tasks" ("id" TEXT PRIMARY KEY,"org_id" TEXT NOT NULL,"project_id" TEXT NOT NULL REFERENCES "projects"("id") ON DELETE CASCADE,"title" TEXT NOT NULL,"description" TEXT,"status" "TaskStatus" NOT NULL DEFAULT 'TODO',"priority" "TaskPriority" NOT NULL DEFAULT 'MEDIUM',"due_date" TIMESTAMP(3),"deleted_at" TIMESTAMP(3),"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "task_assignments" ("id" TEXT PRIMARY KEY,"task_id" TEXT NOT NULL REFERENCES "tasks"("id") ON DELETE CASCADE,"user_id" TEXT NOT NULL REFERENCES "users"("id") ON DELETE CASCADE,"assigned_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE("task_id","user_id"));
CREATE TABLE "comments" ("id" TEXT PRIMARY KEY,"task_id" TEXT NOT NULL REFERENCES "tasks"("id") ON DELETE CASCADE,"user_id" TEXT NOT NULL REFERENCES "users"("id") ON DELETE CASCADE,"body" TEXT NOT NULL,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "refresh_tokens" ("id" TEXT PRIMARY KEY,"user_id" TEXT NOT NULL REFERENCES "users"("id") ON DELETE CASCADE,"token_hash" TEXT NOT NULL UNIQUE,"expires_at" TIMESTAMP(3) NOT NULL,"revoked_at" TIMESTAMP(3),"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "activity_logs" ("id" TEXT PRIMARY KEY,"org_id" TEXT NOT NULL REFERENCES "organizations"("id") ON DELETE CASCADE,"user_id" TEXT REFERENCES "users"("id") ON DELETE SET NULL,"entity_type" TEXT NOT NULL,"entity_id" TEXT NOT NULL,"action" TEXT NOT NULL,"metadata" JSONB,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "outbox_events" ("id" TEXT PRIMARY KEY,"org_id" TEXT NOT NULL REFERENCES "organizations"("id") ON DELETE CASCADE,"type" TEXT NOT NULL,"payload" JSONB NOT NULL,"status" "OutboxStatus" NOT NULL DEFAULT 'PENDING',"attempts" INTEGER NOT NULL DEFAULT 0,"created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"published_at" TIMESTAMP(3));
CREATE INDEX "tasks_org_status_priority_idx" ON "tasks"("org_id","status","priority");CREATE INDEX "tasks_project_created_idx" ON "tasks"("project_id","created_at");CREATE INDEX "activity_entity_idx" ON "activity_logs"("org_id","entity_type","entity_id","created_at");CREATE INDEX "outbox_status_idx" ON "outbox_events"("status","created_at");CREATE INDEX "tasks_search_idx" ON "tasks" USING GIN (to_tsvector('english', coalesce("title",'') || ' ' || coalesce("description",'')));
